insert into cars (id, name, brand, category, price, power_cv, torque_nm, battery_kwh, battery_chem, motor_type, range_km, accel, ground_clearance, trunk_l, weight_kg, wallbox, ac_kw, dc_kw, airbags, warranty, fuel_type, verified, price_verified_date, maintenance_interval, maintenance_first_cost, maintenance_km_base, maintenance_total_cost, consumption_kwh_100, tech_notes, image_url, video_url, personas)
values
  ('ex2max', 'Geely EX2 Max', 'Geely', 'Hatch compacto', 136800, 116, 150, 39, 'LFP', 'PMSM traseiro (RWD)', 289, 10.2, 160, 375, 1480, 'Não incluso', 7, 70, 6, 'Não informado', 'BEV', true, '15/08/2026', '20.000 km ou 12 meses', 'Pago (~R$ 315, fonte alternativa)', 100000, 3264, 13.5, 'Um dos poucos elétricos do segmento com motor traseiro e tração RWD — arquitetura incomum nessa faixa de preço. Bateria LFP de 39 kWh prioriza durabilidade e custo sobre densidade energética, resultando na menor autonomia do grupo.', 'https://static.autodromo.com.br/uploads/8aab83a5-c041-4fa6-9440-b6c458ee1f1b_laGEE002725_ImagensSite_desktop_1920x756px_Design_01.webp', 'https://www.youtube.com/watch?v=Roq_07qi6zo', '{"urbano":5,"familia":2,"aventura":3,"performance":2,"custo":5}'::jsonb),
  ('mg4urban', 'MG4 Urban Luxury 54 kWh', 'MG', 'Hatch médio', 149990, 160, 250, 54, 'LFP', 'PMSM dianteiro (FWD)', 358, 9.5, 117, 568, 1504, 'Não confirmado', 11, 87, 7, '7 anos veículo / 8 anos bateria', 'BEV', true, '15/08/2026', '24.000 km ou 12 meses', 'Pago (R$ 400)', 120000, 3941, 15.1, 'Construído sobre a plataforma MSP (Modular Scalable Platform), a mesma usada na Europa — o que dá respaldo real ao resultado de 5 estrelas do MG4 Electric no Euro NCAP. Química LFP confirmada diretamente na concessionária, após divergência entre fontes públicas. Specs conferidas na ficha técnica oficial MG (ago/2026): porta-malas 568L e altura livre do solo 117mm (valor único de fábrica, igual em todas as versões do MG4 Urban).', 'https://mgmotoroficial.com.br/imagens/new-mg4-urban/banner.jpg', 'https://www.youtube.com/watch?v=iOdnLV552FU', '{"urbano":4,"familia":5,"aventura":3,"performance":3,"custo":5}'::jsonb),
  ('aionut', 'GAC Aion UT Elite', 'GAC', 'Hatch compacto', 159990, 204, 210, 60, 'LFP', 'PMSM dianteiro (FWD)', 310, 7.3, 150, 340, 1520, 'Incluso, sem custo', 6.6, 87, 6, 'Não informado', 'BEV', true, '15/08/2026', '10.000 km ou 12 meses', 'Gratuita', 100000, 6060, 19.4, 'Plataforma AEP 3.0 da GAC, com o motor de 204 cv mais forte do grupo e 0-100 em 7,3s. Bateria LFP de 60 kWh é a maior capacidade da comparação. Vão livre de 150 mm confirmado na concessionária.', 'https://br-www-resouce-cdn.gacgroup.com/static/BR/tenant/cms/common/202606/1780368380304-pc.webp', 'https://www.youtube.com/watch?v=Ro3XSfv8pSw', '{"urbano":4,"familia":3,"aventura":4,"performance":5,"custo":4}'::jsonb),
  ('gac-aion-ut-premium', 'GAC Aion UT Premium', 'GAC', 'Hatch compacto', 139990, 204, 210, 44.12, 'LFP', 'PMSM dianteiro (FWD)', 253, 8.6, NULL, NULL, NULL, NULL, NULL, 64, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'Versão de entrada do Aion UT no Brasil (a Elite já está cadastrada separadamente, id ''aionut''), com bateria menor (44,12kWh vs 60kWh) e carregamento DC mais lento (64kW vs 87kW), resultando em autonomia de 253km vs 310km e aceleração mais lenta (8,6s vs 7,3s). Potência/torque do motor assumidos iguais aos da Elite (204cv/210Nm) — fontes brasileiras não indicam motor diferente entre as versões, só bateria e equipamentos (a Elite tem ADAS nível 2 e teto panorâmico que a Premium não tem).', 'https://br-www-resouce-cdn.gacgroup.com/static/BR/tenant/cms/common/202606/1780368380304-pc.webp', NULL, '{"urbano":4,"familia":3,"aventura":4,"performance":5,"custo":5}'::jsonb),
  ('ora5', 'GWM Ora 5', 'GWM', 'SUV compacto', 159900, 204, 260, 58.3, 'LFP', 'PMSM dianteiro (FWD)', 349, 7.7, 175, 362, 1685, 'Depende de campanha', 11, 120, 6, 'Não informado', 'BEV', true, '15/08/2026', '24.000 km ou 24 meses', 'Pago (R$ 839)', 60000, 2838, 16.7, 'Plataforma Lemon da GWM. Maior vão livre (175 mm) e únicos ângulos de entrada/saída divulgados oficialmente (17°/25°) do grupo — vantagem real para quem enfrenta rampas ou terreno irregular. Único com estepe temporário de fábrica ao lado do Aion UT.', 'https://www.gwmmotors.com.br/content/dam/gwm/pages/br/pt/models/ora-5/lancamento/externas-cinza/ora-5-lateral-rigida-2-gwm-galeria.webp', 'https://www.youtube.com/watch?v=TcEpTAIuw_g', '{"urbano":3,"familia":4,"aventura":5,"performance":5,"custo":3}'::jsonb),
  ('dolphinse', 'BYD Dolphin SE', 'BYD', 'Hatch compacto', 159990, 177, 290, 45.12, 'LFP (Blade)', 'PMSM dianteiro (FWD)', 272, 8, 120, 250, 1485, 'Depende de campanha', 7, 80, 6, '6 anos veículo / 8 anos bateria', 'BEV', true, '15/08/2026', '20.000 km ou 12 meses', 'Pago (R$ 400)', 100000, 3280, 16.6, 'Plataforma e-Platform 3.0 da BYD, com a bateria Blade — LFP com formato estrutural que dispensa módulos intermediários, referência de segurança térmica no setor. Autonomia oficial PBEV (272 km) é mais conservadora que o padrão NEDC usado por parte da imprensa.', 'https://www.byd.com/material/byd-site/br/product/dolphin-se/menu-dolphin-se-4.png', 'https://www.youtube.com/watch?v=KLLBh0NYN1A', '{"urbano":4,"familia":2,"aventura":1,"performance":3,"custo":4}'::jsonb),
  ('geely-ex2-pro', 'Geely EX2 Pro', 'Geely', 'Hatch compacto', 123800, 116, 150, 39.4, 'LFP', 'PMSM traseiro (RWD)', 289, 10.2, 160, 375, 1300, NULL, 6.6, 70, 6, '6 anos veículo / 8 anos bateria (150.000 km)', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 13.6, 'Compartilha com o EX2 Max a mesma plataforma, o motor traseiro (RWD) e a bateria LFP de 39,4 kWh — a versão Pro é a entrada de linha, com potência, torque e autonomia idênticos, mas com pacote de ADAS e itens de conforto reduzidos. Tração traseira é incomum nessa faixa de preço.', 'https://static.autodromo.com.br/uploads/8aab83a5-c041-4fa6-9440-b6c458ee1f1b_laGEE002725_ImagensSite_desktop_1920x756px_Design_01.webp', NULL, '{"urbano":5,"familia":2,"aventura":3,"performance":2,"custo":5}'::jsonb),
  ('jac-e-js1', 'JAC E-JS1', 'JAC', 'Hatch compacto', 132900, 62, 150, 31.4, 'LFP', NULL, 181, 10.7, NULL, 121, 1180, NULL, NULL, NULL, 2, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 17.3, 'Um dos elétricos mais baratos do Brasil, com bateria LFP de 31,4 kWh e a menor autonomia INMETRO do grupo (181 km) — reflexo do foco em uso urbano de curta distância. Apenas 2 airbags (motorista e passageiro), abaixo do padrão de 6 já comum em concorrentes chineses mais recentes.', 'https://www.jacmotors.com.br/wp-content/uploads/2025/12/01-jac-e-js1.webp', NULL, '{"urbano":5,"familia":2,"aventura":2,"performance":1,"custo":4}'::jsonb),
  ('renault-kwid-e-tech', 'Renault Kwid E-Tech', 'Renault', 'Hatch compacto', 99990, 65, 113, 26.8, NULL, 'PMSM dianteiro (FWD)', 180, 14.6, 172, 290, 969, NULL, NULL, 30, 6, '3 anos veículo / 8 anos bateria', 'BEV', true, '17/08/2026', '10.000 km', 'Pago (R$ 320 na 1ª revisão)', 20000, 686, 14.9, 'O elétrico mais barato do Brasil. Autonomia real INMETRO é 180 km (não os 265 km WLTP que circulavam antes) e o consumo real fica em ~14,9 kWh/100km — bem mais alto que o valor otimista anterior. Carregamento DC de 30 kW leva a bateria de 20% a 80% em ~45 min. Vão livre de 172mm é alto pro segmento.', 'https://storage.googleapis.com/ire-74774-ope/files%2F%2Fimage_9e693e33-8699-4d2f-b9af-0d89354507ec.jpg', NULL, '{"urbano":5,"familia":2,"aventura":3,"performance":1,"custo":5}'::jsonb),
  ('renault-megane-e-tech', 'Renault Megane E-Tech', 'Renault', 'Hatch médio', 279990, 220, 300, 60, NULL, 'PMSM dianteiro (FWD)', 337, 7.4, NULL, 440, 1680, NULL, 22, 130, 7, '8 anos/160.000 km bateria', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 17.8, 'Hatch elétrico premium da Renault, com vendas bem baixas no Brasil (32 unidades emplacadas de jan-set/2025). Preço de tabela oficial é R$279.990, mas há descontos agressivos em concessionárias (achado por R$225.990 a R$199.900 em promoções pontuais) por conta do baixo giro de estoque. Recarga DC de 130kW (15-80% em ~36min) e AC de 22kW (carga completa em ~1h50).', 'https://cdn.group.renault.com/ren/br/renault-new-cars/product-plans/2025/megane-/megane_design2.jpg.ximg.xsmall.jpg/696b5a6e02.jpg', NULL, '{"urbano":4,"familia":3,"aventura":2,"performance":4,"custo":2}'::jsonb),
  ('neta-aya', 'Neta Aya', 'Neta', 'Hatch compacto', 128900, 95, 150, 40.7, 'LFP', 'PMSM dianteiro (FWD)', 263, NULL, NULL, 335, 1180, 'Incluso, sem custo', 6.6, 60, NULL, '5 anos/150.000 km veículo, 8 anos/180.000 km bateria e motor', 'BEV', true, '17/08/2026', '20.000 km', 'Gratuita (5 primeiras revisões, fonte única)', NULL, NULL, 15.5, 'Preço de tabela varia por versão: Comfort ~R$128.900, Luxury foi reajustada pra R$149.900 em jan/2026 (era R$134.900 no lançamento). Autonomia oficial PBEV/INMETRO de 263 km é bem confirmada; o consumo foi recalculado pra 15,5 kWh/100km pra bater com essa autonomia real (o valor de 12 kWh/100km batia só com a autonomia WLTP de 338 km, não com a brasileira).', 'https://netaauto.com.br/wp-content/webp-express/webp-images/uploads/2025/06/NETA-AYA-4.png.webp', NULL, '{"urbano":5,"familia":2,"aventura":2,"performance":2,"custo":5}'::jsonb),
  ('gwm-ora-03', 'GWM Ora 03', 'GWM', 'Hatch compacto', 150000, 171, 250, 48, 'LFP', 'PMSM dianteiro (FWD)', 319, 8.2, 135, 228, 1540, 'Depende de campanha', 7.4, NULL, NULL, '5 anos sem limite de km veículo / 8 anos/200.000 km bateria', 'BEV', false, NULL, 'Programa promocional: 5 anos ou 48.000 km de revisões grátis', 'Gratuita (dentro do programa promocional)', 48000, 0, 15, 'Modelo com maior conflito de dados entre fontes: existem duas versões (Skin BEV48 e GT BEV63) com preço, potência e bateria cruzados de forma inconsistente entre sites. Ficha usada aqui é a versão Skin BEV48 (171cv/48kWh), a mais compatível com o preço de tabela. Tem frunk de 57L além dos 228L do porta-malas traseiro. Recomendado checar diretamente no site oficial GWM Brasil antes de decidir.', 'https://www.gwmmotors.com.br/content/dam/gwm/pages/br/pt/models/ora-03-bev58/placas-ajustadas/ora-bev-58-blue.webp', NULL, '{"urbano":4,"familia":2,"aventura":2,"performance":3,"custo":4}'::jsonb),
  ('volvo-ex30', 'Volvo EX30', 'Volvo', 'SUV compacto premium', 239950, 272, 343, 51, 'LFP', 'PMSM traseiro (RWD) — versão Single', 250, NULL, NULL, 318, NULL, NULL, NULL, NULL, 6, '36 meses/100.000 km veículo, 8 anos/160.000 km bateria', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 20.4, 'Existem duas configurações de bateria: Single (51 kWh LFP, RWD, ~250 km INMETRO — ficha usada aqui) e Twin/Extended Range (69 kWh NMC, ~316-338 km — cadastrada separadamente, id volvo-ex30-ultra). Faixa de preço por versão vai de R$212.554 a R$275.485. Houve recall no Brasil (~5.600 unidades) por risco de incêndio na bateria — vale checar se o carro já passou pelo reparo antes de comprar usado.', 'https://www.volvocars.com/images/cs/v3/assets/blt0feaa88e629251fc/bltd6c4bc738c705b81/67bba19c633cc722a1804cfa/Overview-exterior-gallery-2-16x9.jpg?branch=prod_alias&quality=85&format=auto&h=1200&w=1200', NULL, '{"urbano":4,"familia":3,"aventura":2,"performance":4,"custo":2}'::jsonb),
  ('volvo-ex30-ultra', 'Volvo EX30 Ultra Twin Motor', 'Volvo', 'SUV compacto premium', 310000, 428, 543, 69, 'NMC', 'Bimotor AWD (um em cada eixo)', 316, 3.6, NULL, 318, 1960, NULL, NULL, NULL, NULL, '36 meses/100.000 km veículo, 8 anos/160.000 km bateria', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 21.8, 'Versão topo de linha do EX30, bimotor AWD (428cv/543Nm) com bateria NMC de 69kWh — quase o dobro da potência da versão Single (272cv). Existe também a versão Cross Country (R$315.000, mesma bateria de 69kWh, suspensão elevada), provavelmente com potência semelhante à Ultra, mas sem ficha técnica própria confirmada em fonte confiável.', 'https://www.volvocars.com/images/cs/v3/assets/blt0feaa88e629251fc/blt925a50f0601b1430/67bba201335a44fc7f411489/Overview-exterior-gallery-7-16x9.jpg?branch=prod_alias&quality=85&format=auto&h=1200&w=1200', NULL, '{"urbano":3,"familia":4,"aventura":3,"performance":5,"custo":1}'::jsonb),
  ('fiat-500e', 'Fiat 500e', 'Fiat', 'Hatch compacto premium', 219990, 118, 220, 42, NULL, 'PMSM dianteiro (FWD)', 227, 9, NULL, 185, NULL, NULL, 11, 85, NULL, '8 anos/160.000 km bateria', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 18.5, 'Versão de entrada é a Action (R$219.990) — a Icon custa mais. Autonomia WLTP divulgada é 320 km, mas um veículo real registrado rodando no Brasil mediu 227 km com consumo de 18,5 kWh/100km, valores bem mais conservadores usados aqui. DC de 85 kW carrega de 0-80% em ~35 min.', 'https://500e.fiat.com.br/images/HeroDesktop/backgrounds/fiat-500e-novo-500-eletrico.webp', NULL, '{"urbano":5,"familia":1,"aventura":1,"performance":2,"custo":2}'::jsonb),
  ('peugeot-e-2008', 'Peugeot e-2008', 'Peugeot', 'SUV compacto premium', 259990, 158, 260, 54, NULL, 'PMSM dianteiro (FWD)', 261, NULL, NULL, 434, NULL, NULL, 11, 100, 6, '2 anos veículo + 8 anos bateria', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 20.7, 'Nova geração eleva a potência pra 158cv (a versão anterior tinha 136cv) e a bateria pra 54 kWh (era 50 kWh). Autonomia oficial PBEV/INMETRO é 261 km — bem abaixo do WLTP europeu de 345 km. AC trifásico de 11 kW e DC de até 100 kW (0-80% em ~30 min). Preço de tabela vai de R$259.990 a R$269.990 conforme versão.', 'https://www.peugeot.pt/content/dam/peugeot/portugal/b2c/our-range/e-2008-suv/canvas-aug25/E-2008_1920x1080-1.jpg', NULL, '{"urbano":3,"familia":4,"aventura":2,"performance":3,"custo":2}'::jsonb),
  ('mini-cooper-se', 'Mini Cooper SE', 'Mini', 'Hatch compacto premium', 259990, 218, 330, 54.2, NULL, 'PMSM dianteiro (FWD)', 303, 6.7, NULL, 210, 1540, 'Incluso, sem custo', 11, NULL, NULL, NULL, 'BEV', true, '17/08/2026', NULL, 'Incluso no pacote MINI Service Inclusive (4 anos, km ilimitado)', NULL, NULL, 17.9, 'Um dos modelos mais consistentes entre as fontes pesquisadas — poucas divergências. Porta-malas de 210L (800L com bancos rebatidos). O pacote MINI Service Inclusive (4 anos, km ilimitado) inclui um MINI Wallbox Essential 11kW de cortesia. Carga AC completa em ~5h15.', 'https://www.mini.com.br/content/dam/MINI/common/Range/new-generation/cooper/all-electric/bodytype-hub/mini-J01-BEV-gallery-front-wide.webp', NULL, '{"urbano":5,"familia":1,"aventura":1,"performance":4,"custo":2}'::jsonb),
  ('mini-aceman-e', 'Mini Aceman E', 'Mini', 'Hatch compacto premium', 254990, 184, 290, 42.5, NULL, 'PMSM dianteiro (FWD)', 253, 7.6, NULL, 300, NULL, NULL, NULL, NULL, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 16.8, 'Primeiro modelo da MINI projetado desde o início pra ser 100% elétrico, posicionado entre o hatch Cooper e o SUV Countryman. Versão de entrada (E), com bateria de 42,5kWh e 253km de autonomia (Inmetro) — dados confirmados via press release oficial do BMW Group Brasil. Porta-malas de 300L (1.005L com bancos rebatidos). A versão SE (mais potente) está cadastrada separadamente (id mini-aceman-se). Recarga DC 10-80% em ~28min.', 'https://www.mini.com.br/content/dam/MINI/common/Range/new-generation/aceman/bodytype-hub/mini-J05-gallery-exterior.webp', NULL, '{"urbano":5,"familia":2,"aventura":2,"performance":3,"custo":2}'::jsonb),
  ('mini-aceman-se', 'Mini Aceman SE', 'Mini', 'Hatch compacto premium', 304990, 218, 330, 54.2, NULL, 'PMSM dianteiro (FWD)', 270, 7.1, NULL, 300, 1785, NULL, NULL, NULL, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 20.1, 'Versão topo de linha do Aceman, com bateria maior (54,2kWh vs 42,5kWh da E) e mais potência (218cv vs 184cv), resultando em mais autonomia (270km vs 253km, Inmetro) e aceleração mais rápida (7,1s vs 7,6s). Porta-malas de 300L (1.005L com bancos rebatidos). Recarga DC 10-80% em ~31min.', 'https://www.mini.com.br/content/dam/MINI/common/Range/new-generation/aceman/bodytype-hub/mini-J05-gallery-exterior.webp', NULL, '{"urbano":5,"familia":2,"aventura":2,"performance":4,"custo":1}'::jsonb),
  ('mini-countryman-se-all4', 'MINI Countryman SE ALL4', 'Mini', 'SUV compacto premium', 409990, 306, 494, 66.45, NULL, 'Bimotor AWD (ALL4)', 320, 5.8, NULL, 450, NULL, NULL, NULL, 130, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 20.8, 'SUV elétrico da MINI, compartilha plataforma com o BMW iX1/iX2. Versões Exclusive (R$294.990) e Top (R$339.990) têm a mesma mecânica (306cv/494Nm/66,45kWh) — só rodas e equipamentos mudam, por isso um card único. Preço oficial atual (site MINI Brasil, ago/2026) é R$409.990, bem acima dos valores de lançamento. Porta-malas de 450L (1.390L com bancos rebatidos). Recarga DC de até 130kW (10-80% em ~30min).', 'https://www.mini.com/content/dam/MINI/common/Range/new-generation/countryman/bev/bodytype-hub/mini-U25-BEV-campaign-wide.webp', NULL, '{"urbano":3,"familia":4,"aventura":2,"performance":5,"custo":1}'::jsonb),
  ('chevrolet-equinox-ev', 'Chevrolet Equinox EV', 'Chevrolet', 'SUV médio', 419000, 292, 451, 85, 'NCMA', 'Bimotor AWD (2x146cv)', 443, 5.8, NULL, 441, 2336, NULL, NULL, NULL, 8, '8 anos/160.000 km bateria (confirmar termo exato Brasil)', 'BEV', true, '17/08/2026', NULL, 'Gratuita (1ª revisão aos 10.000 km)', NULL, NULL, 19.2, 'Preço real de tabela é ~R$419.000 — bem acima do valor de R$299.990 que circulava antes. Bateria NCMA (evolução da química NMC, com menos cobalto) de 85 kWh, a maior do grupo, com motor biMotor AWD de 2x146cv somando 292cv e 451Nm.', 'https://www.chevrolet.com.br/content/dam/chevrolet/south-america/brazil/portuguese/index/electric/guide/guias-equinox-ev/mh-equinox-desk.jpg?imwidth=1200', NULL, '{"urbano":2,"familia":5,"aventura":3,"performance":4,"custo":1}'::jsonb),
  ('chevrolet-blazer-ev', 'Chevrolet Blazer EV RS', 'Chevrolet', 'SUV médio', 503190, 347, 450, 102, NULL, 'PMSM traseiro (RWD)', 526, 5.8, NULL, 764, 2495, NULL, 22, 190, 8, '8 anos/160.000 km bateria', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 19.4, 'SUV elétrico esportivo da plataforma Ultium (mesma base do Equinox EV), vendido no Brasil só na versão RS (motor único traseiro, 347cv/450Nm). Preço subiu de R$479.000 no lançamento (2024) para R$503.190 atualmente. Autonomia declarada varia entre 481km (Inmetro, fonte de lançamento) e 526km (fonte mais recente) — usamos a mais recorrente. Uma versão AWD (305cv, bateria menor de 85kWh) foi anunciada para 2026 mas ainda sem ficha e preço confiáveis publicados.', 'https://www.chevrolet.com.br/content/dam/chevrolet/south-america/brazil/portuguese/index/visid/electric/2025-blazer-ev/01-images/mov/01-images/imagem-balzer-ev.jpg?imwidth=1200', NULL, '{"urbano":2,"familia":5,"aventura":3,"performance":5,"custo":1}'::jsonb),
  ('chevrolet-captiva-ev', 'Chevrolet Captiva EV Premier', 'Chevrolet', 'SUV médio', 199990, 201, 310, 60, 'LFP', 'PMSM dianteiro (FWD)', 304, 9.9, NULL, 400, NULL, NULL, NULL, 120, 6, '8 anos/160.000 km bateria', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 19.6, 'SUV elétrico familiar de produção nacional (Polo Automotivo do Ceará, junto com o Spark EUV), vendido só na versão Premier. Bateria LFP de 60kWh, motor único dianteiro de 201cv/310Nm. Preço oficial de lançamento é R$199.990 — algumas fontes mais recentes citam R$219.990, possivelmente um reajuste ainda não confirmado em múltiplas fontes. DC de até 120kW (30-80% em ~30min).', 'https://www.chevrolet.com.br/content/dam/chevrolet/south-america/brazil/portuguese/index/visid/electric/captiva-ev/mov/banner-01/chevrolet-captiva-ev-suv-urbano.jpg?imwidth=1200', NULL, '{"urbano":3,"familia":5,"aventura":3,"performance":3,"custo":3}'::jsonb),
  ('chevrolet-spark-euv', 'Chevrolet Spark EUV', 'Chevrolet', 'SUV compacto', 144990, 102, 180, 41.9, NULL, 'PMSM dianteiro (FWD)', 258, 11, NULL, 355, NULL, NULL, 7, NULL, NULL, '3 anos veículo (garantia de bateria não confirmada)', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 16.1, 'Mini SUV elétrico de entrada da Chevrolet no Brasil, com motor único dianteiro de 102cv/180Nm e bateria de 41,9kWh. Porta-malas de 355L (916L com bancos rebatidos). Carregador de parede (wall charger) de 7kW leva de 20% a 100% em ~7h; carregamento DC não confirmado em fonte confiável.', 'https://www.chevrolet.com.br/content/dam/chevrolet/south-america/brazil/portuguese/index/visid/electric/spark-euv/refresh/gallery/fechada/chevrolet-spark-euv.jpeg?imwidth=1200', NULL, '{"urbano":4,"familia":3,"aventura":2,"performance":1,"custo":4}'::jsonb),
  ('volvo-ex40', 'Volvo EX40', 'Volvo', 'SUV médio premium', 329950, 238, 420, 69, NULL, 'PMSM traseiro (RWD) — versão P6', 385, NULL, NULL, 414, 2050, NULL, NULL, NULL, 7, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 17.9, 'Antigo Volvo XC40 Recharge, renomeado EX40 em 2025. Duas versões: P6 (238cv/420Nm, RWD, bateria 69kWh, ~385km — ficha usada aqui, compatível com o preço de tabela Plus de R$329.950) e P8 (408cv/670Nm, AWD, bateria 82kWh, ~393km, 0-100 em 4,9s, mais cara — cadastrada separadamente, id volvo-ex40-ultra). Peso ~2.050kg é aproximado (fonte não especifica por versão).', 'https://www.volvocars.com/images/cs/v3/assets/blt0feaa88e629251fc/blt5fe2e0ad60256848/685251c2c6e1436bffd9bde6/overview-exterior-gallery-16x9.jpg?branch=prod_alias&quality=85&format=auto&h=1200&w=1800', NULL, '{"urbano":3,"familia":4,"aventura":3,"performance":3,"custo":1}'::jsonb),
  ('volvo-ex40-ultra', 'Volvo EX40 Ultra P8', 'Volvo', 'SUV médio premium', 375700, 408, 670, 82, NULL, 'Bimotor AWD', 393, 4.9, NULL, 414, NULL, NULL, NULL, NULL, 7, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 20.9, 'Versão topo de linha do EX40 (P8 Ultra AWD), com bateria maior (82kWh vs 69kWh do P6) e bimotor (408cv/670Nm vs 238cv/420Nm), quase dobrando a potência. Preço tem bastante divergência entre fontes/datas — de R$329.703 (FIPE) a R$375.700 (maio/2026); usamos o valor mais recente encontrado. Porta-malas e airbags assumidos iguais ao P6 (mesma carroceria).', 'https://www.volvocars.com/images/cs/v3/assets/blt0feaa88e629251fc/blt36d2dc5cfa41f957/6852527a8319c416c2d91a22/overview-exterior-gallery-02-16x9.jpg?branch=prod_alias&quality=85&format=auto&h=1200&w=1200', NULL, '{"urbano":3,"familia":4,"aventura":3,"performance":5,"custo":1}'::jsonb),
  ('volvo-ec40-plus', 'Volvo EC40 Plus', 'Volvo', 'SUV médio premium', 334950, 238, 420, 69, NULL, 'PMSM traseiro (RWD)', 385, 7.4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 17.9, 'Antigo Volvo C40 Recharge, renomeado EC40 em 2025 — versão cupê-SUV do EX40, com carroceria de teto mais baixo e inclinado, mas mesma base mecânica. Versão Plus (RWD, 238cv/420Nm, bateria 69kWh, ~385km Inmetro) é a entrada de linha. A versão Ultra (bimotor, mais potente) está cadastrada separadamente (id volvo-ec40-ultra). Porta-malas provavelmente menor que o EX40 (carroceria cupê), mas sem fonte confiável específica.', 'https://www.volvocars.com/images/cs/v3/assets/blt0feaa88e629251fc/blt5e9113fe09dfe427/685bf946947f79a03951f0cf/overview-exterior-gallery-16x9.jpg?branch=prod_alias&quality=85&format=auto&h=1200&w=1800', NULL, '{"urbano":3,"familia":3,"aventura":2,"performance":3,"custo":1}'::jsonb),
  ('volvo-ec40-ultra', 'Volvo EC40 Ultra', 'Volvo', 'SUV médio premium', 384950, 408, 670, 82, NULL, 'Bimotor AWD', 404, 4.8, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 20.3, 'Versão topo de linha do EC40 (bimotor AWD, 408cv/670Nm, bateria 82kWh), com a maior autonomia da linha 2026 (404km Inmetro, +51km sobre a geração anterior). Mesmo conjunto mecânico do EX40 Ultra, em carroceria cupê-SUV.', 'https://www.volvocars.com/images/cs/v3/assets/blt0feaa88e629251fc/bltdd9a3cddf17c1565/685bfa259f3389c127e2015d/overview-exterior-gallery-02-16x9.jpg?branch=prod_alias&quality=85&format=auto&h=1200&w=1200', NULL, '{"urbano":3,"familia":3,"aventura":2,"performance":5,"custo":1}'::jsonb),
  ('bmw-ix1', 'BMW iX1 eDrive20', 'BMW', 'SUV compacto premium', 359950, 204, 250, 64.7, NULL, 'PMSM dianteiro (FWD)', 332, NULL, NULL, 490, NULL, NULL, NULL, NULL, NULL, '8 anos/160.000 km bateria', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 19.5, 'Existem duas versões: eDrive20 (FWD, R$359.950, 204cv/250Nm, bateria 64,7kWh, ~332km INMETRO — ficha usada aqui) e xDrive30 M Sport (AWD, R$485.950, 313cv/494Nm, bateria 66,5kWh, ~303km INMETRO). O preço que circulava antes (R$339.990 com 313cv) não corresponde a nenhuma das duas versões reais.', 'https://bmw.scene7.com/is/image/BMW/u11-bev_stage:16to7?fmt=webp&wid=2560&fit=wrap%2C+1', NULL, '{"urbano":3,"familia":4,"aventura":2,"performance":2,"custo":1}'::jsonb),
  ('bmw-ix2', 'BMW iX2 xDrive30 M Sport', 'BMW', 'SUV compacto premium', 495950, 313, 494, 64.8, NULL, 'Bimotor AWD (um motor em cada eixo)', 337, 5.6, NULL, 525, NULL, 'Depende de campanha', 22, 130, NULL, '8 anos bateria (garantia do veículo BMW não confirmada com fonte clara)', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 20, 'Versão elétrica cupê-SUV do X2, voltou a ser vendida oficialmente no Brasil (o iX2 já havia ficado fora de linha por um tempo). Bimotor AWD com 313cv/494Nm combinados. Preço de tabela oficial de agosto/2026 é R$495.950 — fontes de imprensa mais antigas (de 2024/2025) mencionam valores de R$443.950 a R$464.950, defasados pelos reajustes ao longo do período. Porta-malas de 525L (até 1.400L com bancos rebatidos).', 'https://bmw.scene7.com/is/image/BMW/u10_bev_design-positioning:16to7?fmt=webp&wid=2560&fit=wrap%2C+1', NULL, '{"urbano":3,"familia":4,"aventura":2,"performance":5,"custo":1}'::jsonb),
  ('bmw-ix3', 'BMW iX3 50 xDrive', 'BMW', 'SUV médio premium', 582950, 469, 645, 108.7, NULL, 'Bimotor AWD (um motor em cada eixo)', 570, 4.9, NULL, 520, NULL, NULL, 22, 400, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 19.1, 'Nova geração do iX3, estreou em pré-venda no Brasil em jul/2026 por R$582.950 — ''nova era'' de plataforma elétrica da marca (arquitetura 800V, células cilíndricas integradas à estrutura). Maior autonomia declarada entre elétricos vendidos no país (570km PBEV/Inmetro). Carregamento DC de até 400kW (10-80% em ~21min). Consumo de 19,1 kWh/100km calculado a partir de bateria/autonomia oficiais (não divulgado diretamente pela BMW). Por estar em fase de pré-venda, unidades ainda podem não estar disponíveis para entrega imediata.', 'https://bmw.scene7.com/is/image/BMW/na5_exterior_front_view_1920_1024_fb?qlt=80&wid=2000&fmt=webp', NULL, '{"urbano":3,"familia":4,"aventura":3,"performance":5,"custo":1}'::jsonb),
  ('bmw-ix', 'BMW iX xDrive50 Sport', 'BMW', 'SUV grande premium', 923950, 523, 765, 111.5, NULL, 'Bimotor AWD sob demanda', 528, 4.6, NULL, 500, 2585, NULL, NULL, 195, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 21.1, 'SUV grande elétrico topo da linha i da BMW, R$923.950 (preço de tabela válido até 31/08/2026). Bimotor AWD sob demanda com 523cv/765Nm. Também existe a versão de entrada iX xDrive40 (a partir de R$726.950, motor único, bateria menor), não detalhada aqui por falta de ficha técnica completa confiável. Consumo de 21,1 kWh/100km calculado a partir de bateria/autonomia oficiais.', 'https://bmw.scene7.com/is/image/BMW/i20_bev_stage_dsk_fb?qlt=80&wid=2000&fmt=webp', NULL, '{"urbano":2,"familia":5,"aventura":3,"performance":5,"custo":1}'::jsonb),
  ('bmw-i4', 'BMW i4 eDrive40 M Sport', 'BMW', 'Sedã médio premium', 582950, 340, 430, 81.3, NULL, 'PMSM traseiro (RWD)', 422, 5.7, NULL, 470, NULL, NULL, NULL, NULL, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 19.3, 'Gran Coupé elétrico (liftback 4 portas), motor traseiro único de 340cv/430Nm. Preço de tabela oficial de agosto/2026 é R$582.950. Autonomia tem alguma divergência entre fontes (399 a 422km PBEV/Inmetro conforme a fonte) — usamos aqui a mais recorrente. Porta-malas de 470L (1.290L com bancos rebatidos).', 'https://bmw.scene7.com/is/image/BMW/g26_bev_stage_dsk_fb?qlt=80&wid=2000&fmt=webp', NULL, '{"urbano":4,"familia":4,"aventura":2,"performance":5,"custo":1}'::jsonb),
  ('bmw-i5', 'BMW i5 M60 xDrive', 'BMW', 'Sedã grande premium', 795950, 601, 820, 81.2, NULL, 'Bimotor AWD sob demanda', 391, NULL, NULL, 490, NULL, NULL, NULL, 205, NULL, NULL, 'BEV', false, NULL, NULL, NULL, NULL, NULL, 20.8, 'Sedã executivo elétrico, versão M60 xDrive (única versão vendida no Brasil), bimotor AWD com 601cv/820Nm combinados. Chegou ao Brasil em mar/2024 por R$759.950; fontes mais recentes (2025/2026) mencionam R$795.950, mas não achamos confirmação oficial datada de ago/2026 — trate o preço como aproximado até checar na concessionária. DC de até 205kW (10-80% em ~30min).', 'https://bmw.scene7.com/is/image/BMW/g60-mp-bev-stage-ext-dsk-sl?qlt=80&wid=2000&fmt=webp', NULL, '{"urbano":2,"familia":4,"aventura":1,"performance":5,"custo":1}'::jsonb),
  ('bmw-i7', 'BMW i7 xDrive60 M Sport', 'BMW', 'Sedã grande premium', 1373950, 544, 745, 101.7, NULL, 'Bimotor AWD', 512, 4.7, NULL, 515, 2715, NULL, NULL, NULL, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 19.9, 'Sedã executivo elétrico topo de linha da BMW (versão elétrica do Série 7), R$1.373.950 — preço confirmado em vários concessionários oficiais em ago/2026. Bimotor AWD com 544cv/745Nm combinados, bateria de 101,7kWh. Recarga DC de 10-80% em ~34min.', 'https://bmw.scene7.com/is/image/BMW/g70-bev_stage:16to7?fmt=webp&wid=2560&fit=wrap%2C+1', NULL, '{"urbano":1,"familia":4,"aventura":1,"performance":5,"custo":1}'::jsonb),
  ('bmw-530e', 'BMW 530e M Sport', 'BMW', 'Sedã grande híbrido', NULL, 299, 450, 19.4, NULL, 'PHEV combinado (2.0 turbo 190cv + elétrico 184cv) — RWD', NULL, NULL, NULL, 520, NULL, NULL, NULL, NULL, NULL, NULL, 'PHEV', false, NULL, NULL, NULL, NULL, NULL, NULL, 'Sedã executivo híbrido plug-in (Série 5), conjunto combinado de 299cv/450Nm com bateria de 19,4kWh e ~61km de autonomia elétrica pura. Preço não confirmado com segurança — fontes de 2026 divergem muito entre si (de R$456.706 a R$643.950), possivelmente por diferença de ano-modelo/pacotes; deixado como null até confirmar diretamente na concessionária.', 'https://bmw.scene7.com/is/image/BMW/g60_phev_ext-design-highlights_2_dynamic-light-carpet_dsk_shfv_de?qlt=80&wid=2000&fmt=webp', NULL, '{"urbano":2,"familia":4,"aventura":1,"performance":4,"custo":2}'::jsonb),
  ('bmw-x5-xdrive50e', 'BMW X5 xDrive50e M Sport', 'BMW', 'SUV híbrido premium', 864950, 489, 700, 25.7, NULL, 'PHEV combinado (3.0 I6 turbo 313cv + elétrico) — AWD', NULL, 4.8, NULL, 500, NULL, NULL, 22, NULL, NULL, NULL, 'PHEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'SUV grande híbrido plug-in, motor a combustão 3.0 I6 turbo (313cv) somado a elétrico, com potência combinada de 489cv/700Nm. Preço de tabela R$864.950 (ago/2026). Bateria de 25,7kWh com ~76km de autonomia elétrica pura. AC de 22kW.', 'https://bmw.scene7.com/is/image/BMW/1-x5-header:16to7?fmt=webp&wid=2560&fit=wrap%2C+1', NULL, '{"urbano":2,"familia":5,"aventura":3,"performance":5,"custo":1}'::jsonb),
  ('hyundai-ioniq-5', 'Hyundai Ioniq 5', 'Hyundai', 'SUV médio premium', 394990, 325, 604, 84, 'NMC', 'Bimotor AWD (plataforma E-GMP)', 374, 5.3, 178, 527, NULL, 'Incluso, sem custo', 11, 350, 8, '5 anos sem limite de km veículo (inclui carregador residencial) + 8 anos/160.000 km bateria e motores', 'BEV', true, '17/08/2026', NULL, '~R$1.200/revisão (confiança moderada, sem tabela oficial detalhada)', NULL, NULL, 22.5, 'Preço de lançamento (Signature) é R$394.990 — acima do valor de R$339.990 que circulava antes (havia descontos pontuais de estoque parado até R$294.990, mas não é preço de tabela). Autonomia oficial PBEV/INMETRO é 374 km, bem abaixo do WLTP de 480 km. DC de até 350 kW carrega de 10-80% em ~18 min. Wallbox residencial WEG 7,68kW incluso, com 1 ano de cobertura.', 'https://www.hyundai.com.br/content/dam/hmb/product/ioniq-5/_new-assets/mkv/ioniq5_mkv_desk_1920x800.webp', NULL, '{"urbano":2,"familia":5,"aventura":3,"performance":5,"custo":1}'::jsonb),
  ('jetour-t2-phev', 'Jetour T2 PHEV', 'Jetour', 'SUV híbrido', 289900, 339, 510, 26.7, NULL, 'PHEV combinado (1.5 turbo ~128-135cv + elétrico 225cv)', 1100, 7.5, 205, NULL, 2110, NULL, 7, 40, 6, '7 anos completa + 8 anos/160.000 km bateria e motor elétrico', 'PHEV', false, NULL, NULL, NULL, NULL, NULL, NULL, 'Preço real de tabela é R$289.900 (Advance) a R$299.900 (Premium) — bem acima do valor anterior de R$189.990. Potência combinada real é de até 339cv (motor 1.5 turbo + elétrico), não 197cv. Autonomia elétrica pura ~75km (fontes variam entre 70-77km). Consumo híbrido de 11,4 km/L no ciclo urbano (gasolina). Porta-malas tem conflito entre fontes (450L vs 580L). Carregamento AC 7kW / DC 40kW (20-80% em ~30-36min).', 'https://jetourbr.com/wp-content/uploads/2026/03/jetour-t2-hero.webp', NULL, '{"urbano":2,"familia":4,"aventura":4,"performance":4,"custo":1}'::jsonb),
  ('jetour-s06', 'Jetour S06', 'Jetour', 'SUV híbrido', 204900, 315, 510, 19.43, 'LFP', 'PHEV combinado (1.5 turbo 135cv + elétrico 204cv) — FWD', 1200, 7.9, NULL, 416, NULL, NULL, NULL, NULL, 6, '7 anos/150.000 km veículo + 8 anos/160.000 km bateria', 'PHEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'SUV de entrada da Jetour no Brasil, marca que estreou no país em 2026 com 3 modelos PHEV (S06, T1 e T2, este já cadastrado separadamente). Mesmo conjunto mecânico do T1 (1.5 turbo 135cv + elétrico 204cv, 315cv/510Nm combinados), mas com bateria menor (19,43kWh vs 26,7kWh), resultando em menos autonomia elétrica (70km vs 88km). Preço subiu de R$199.900 (pré-venda) pra R$204.900 (Advance, a partir de mai/2026); versão Premium custa R$239.900.', 'https://jetourbr.com/wp-content/uploads/2026/03/jetour-s06-hero.webp', NULL, '{"urbano":3,"familia":4,"aventura":3,"performance":5,"custo":2}'::jsonb),
  ('jetour-t1', 'Jetour T1', 'Jetour', 'SUV híbrido', 254900, 315, 510, 26.7, 'LFP', 'PHEV combinado (1.5 turbo 135cv + elétrico 204cv) — FWD', 1200, 8.7, NULL, 574, 2000, NULL, NULL, NULL, 6, '7 anos/150.000 km veículo + 8 anos/160.000 km bateria', 'PHEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'SUV intermediário da Jetour, entre o S06 (mais barato) e o T2 (mais caro/potente). Mesmo conjunto mecânico do S06 (315cv/510Nm), mas bateria maior (26,7kWh vs 19,43kWh) e mais autonomia elétrica (88km vs 70km) e porta-malas maior (574L vs 416L, até 1.455L com bancos rebatidos). Preço Advance subiu de R$249.900 (pré-venda) pra R$254.900 (a partir de mai/2026); versão Premium custa R$274.900.', 'https://jetourbr.com/wp-content/uploads/2026/03/jetour-t1-hero.webp', NULL, '{"urbano":3,"familia":4,"aventura":3,"performance":5,"custo":1}'::jsonb),
  ('jaecoo-7-phev', 'JAECOO 7 PHEV', 'JAECOO', 'SUV híbrido', 234990, 279, NULL, 18.3, 'LFP', 'PHEV combinado (1.5 turbo 135cv + elétrico 204cv)', 1100, 8.5, NULL, 500, 1795, NULL, NULL, NULL, 7, '7 anos ou 150.000 km', 'PHEV', false, NULL, '12 meses/10.000 km, grátis nos 3 primeiros anos', 'Gratuita (3 primeiros anos)', NULL, NULL, NULL, 'Preço varia por versão: Elite R$179.990, Luxury R$234.990 (ficha usada aqui), Prestige R$256.990 — nenhuma bate exatamente com o valor anterior de R$199.990. A marca mudou a metodologia de medição de potência (UN R21): hoje anuncia 279cv pro mesmo conjunto mecânico (1.5 turbo 135cv + elétrico 204cv) que antes era anunciado com 339cv. Autonomia elétrica pura de 79km (INMETRO, bem confirmada). Consumo híbrido de 15,1 km/L urbano.', 'https://cms.omodajaecoo.com.br/images/vehicles-content/1665511444-j7_box-top_desk-v4.jpg', NULL, '{"urbano":3,"familia":4,"aventura":3,"performance":4,"custo":2}'::jsonb),
  ('gwm-haval-h6-phev', 'GWM Haval H6 PHEV19', 'GWM', 'SUV híbrido', 248000, 326, 540, 19, 'LFP (SVOLT)', 'PHEV combinado', 1200, 7.4, NULL, 560, NULL, NULL, 6.6, 33, 6, '5 anos sem limite de km veículo + 8 anos/200.000 km sistema híbrido e bateria', 'PHEV', true, '17/08/2026', '12.000 km/12 meses', 'Conflito entre fontes: grátis ou ~R$890', NULL, NULL, NULL, 'Existem 4 variantes do Haval H6 em 2026: HEV2 (não é PHEV, R$223 mil), PHEV19 (ficha usada aqui, 326cv, R$248 mil — preço atualizado, o valor anterior de R$219.800 estava desatualizado), PHEV35 (393cv, R$288 mil) e GT (393cv, carroceria cupê, R$325 mil). Autonomia elétrica pura de 77km INMETRO (até 115km WLTP). Um dos poucos PHEVs com carregamento DC (até 33kW), incomum no segmento.', 'https://www.gwmmotors.com.br/content/dam/gwm/pages/br/pt/models/haval-h6-phev19-my25/lancamento-/phev-19-3-4-dianteira-ambientada.webp', NULL, '{"urbano":2,"familia":4,"aventura":4,"performance":5,"custo":2}'::jsonb),
  ('gwm-tank-300', 'GWM Tank 300 Hi4-T', 'GWM', 'SUV híbrido', 342000, 394, 750, 37.1, 'NMC', 'PHEV combinado 4x4 (2.0 turbo 245cv + elétrico dianteiro 163cv)', 1290, 6.8, NULL, 863, 2630, NULL, NULL, NULL, 6, '5 anos sem limite de km veículo + 8 anos/200.000 km sistema híbrido e bateria', 'PHEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'SUV off-road de luxo, híbrido plug-in 4x4 com 394cv/750Nm combinados, bateria 37,1kWh NMC e autonomia elétrica pura de 74-75km (Inmetro) / até 106km (WLTP). Preço oficial no site da GWM Brasil é R$342.000 — agregadores de mercado citam valores de R$333.000 (lançamento, 2025) a R$389.990, possível reflexo de diferentes datas/versões. Autonomia total combinada (~1.290km) é uma estimativa calculada a partir do consumo híbrido divulgado (18,4-18,7 km/l) e do tanque de 70L — não é um valor divulgado diretamente pela GWM. Porta-malas de 863L (1.520L com bancos rebatidos).', 'https://www.gwmmotors.com.br/content/dam/gwm/pages/br/pt/models/tank-300/gerais/banner-hero-tank-300.webp', NULL, '{"urbano":1,"familia":3,"aventura":5,"performance":5,"custo":1}'::jsonb),
  ('gwm-wey-07', 'GWM WEY 07', 'GWM', 'SUV híbrido', 429000, 517, 820, 42.5, NULL, 'PHEV combinado AWD (1.5 turbo + dois motores elétricos, um em cada eixo)', 1200, 4.9, NULL, 239, 2545, NULL, NULL, NULL, 6, NULL, 'PHEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'SUV híbrido plug-in de luxo com 6 lugares da WEY, submarca premium da GWM. Lançado oficialmente no Brasil em out/2025 (vendas iniciadas em 23/10), preço R$429.000. Potência combinada de 517cv/820Nm, bateria 42,5kWh, autonomia elétrica de 128km (Inmetro) — até 185km citado em fonte WLTP. Autonomia total combinada supera 1.200km. Porta-malas de apenas 239L com a 3ª fileira em uso (1.040L com ela rebatida). Garantia não confirmada em fonte disponível.', 'https://www.gwmmotors.com.br/content/dam/gwm/pages/br/pt/models/wey/wey-lateral.png', NULL, '{"urbano":2,"familia":5,"aventura":3,"performance":5,"custo":1}'::jsonb),
  ('byd-dolphin', 'BYD Dolphin', 'BYD', 'Hatch compacto', 149800, 95, 180, 44.9, 'LFP (Blade)', 'PMSM dianteiro (FWD)', 320, 7, NULL, 345, 1410, NULL, 7, 40, 6, '8 anos/150.000 km bateria', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 14, 'Autonomia WLTP divulgada é de até 340km; usamos aqui uma estimativa mais realista de uso urbano (290-320km). Bateria Blade LFP, mesma tecnologia usada em toda a linha BYD, com estrutura que dispensa módulos intermediários. 5 estrelas no Latin NCAP.', 'https://www.byd.com/material/byd-site/america-public/header-product-image/dolphin-header-update.png', NULL, '{"urbano":5,"familia":2,"aventura":1,"performance":2,"custo":4}'::jsonb),
  ('byd-dolphin-plus', 'BYD Dolphin Plus', 'BYD', 'Hatch compacto', 178800, 204, NULL, 60.5, 'LFP (Blade)', 'PMSM dianteiro (FWD)', 420, 5.9, NULL, NULL, NULL, NULL, 7, 60, NULL, '8 anos/150.000 km bateria', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 14.4, 'Versão de maior autonomia da linha Dolphin, com bateria maior (60,5kWh) que a versão padrão. Fontes de preço variam entre R$168.800 e R$178.800 conforme configuração. DC de 60kW carrega de 20% a 80% em ~45min.', 'https://www.byd.com/material/byd-site/br/product/dolphin-plus/section02.jpg', NULL, '{"urbano":4,"familia":2,"aventura":1,"performance":4,"custo":3}'::jsonb),
  ('byd-yuan-plus', 'BYD Yuan Plus', 'BYD', 'SUV compacto', 229800, 204, 310, 60.5, 'LFP', 'PMSM dianteiro (FWD)', 294, 7.3, NULL, 440, 1690, NULL, NULL, NULL, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 20.6, 'Conhecido internacionalmente como BYD Atto 3. Preço real de tabela é R$229.800 — acima dos R$189.800 que circulavam antes. Autonomia PBEV/Inmetro de 294km é a oficial no Brasil (a autonomia CLTC chinesa de 510km, bem mais otimista, não se aplica aqui).', 'https://www.byd.com/material/byd-site/br/product/yuan-plus-ev-br/yuanplus-2026/yuan-2026/menu_yuan-plus-2026-2.png', NULL, '{"urbano":3,"familia":4,"aventura":3,"performance":4,"custo":2}'::jsonb),
  ('byd-atto-2-gl', 'BYD Atto 2 DM-i Flex GL', 'BYD', 'SUV compacto', 149990, 177, 300, 7.3, 'LFP (Blade)', 'PHEV combinado flex (1.5 gasolina/etanol + elétrico) — DM-i Flex', 1000, 8.5, NULL, 455, NULL, NULL, 3.3, NULL, 6, '6 anos/200.000 km veículo + 8 anos/200.000 km bateria Blade', 'PHEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'Estreia mundial do sistema híbrido plug-in DM-i Flex da BYD — primeiro PHEV do mundo capaz de rodar com gasolina OU etanol. Lançado no Brasil em 9/jun/2026, fabricado em Camaçari (BA). Versão de entrada GL: bateria pequena (7,3kWh), autonomia elétrica de só 45km, carregamento AC de até 3,3kW. Autonomia combinada de 1.000km (gasolina, ciclo NEDC) ou 770km (etanol). Vendida inicialmente por canal de venda direta. A versão GS (mais equipada, com ADAS 2) está cadastrada separadamente (id byd-atto-2-gs).', 'https://www.byd.com/material/byd-site/br/product/atto-2-dmi/atto2-header.webp', NULL, '{"urbano":3,"familia":4,"aventura":3,"performance":3,"custo":3}'::jsonb),
  ('byd-atto-2-gs', 'BYD Atto 2 DM-i Flex GS', 'BYD', 'SUV compacto', 169990, 197, 300, 18, 'LFP (Blade)', 'PHEV combinado flex (1.5 gasolina/etanol + elétrico) — DM-i Flex', 1045, 8.4, NULL, 455, NULL, NULL, 6.6, NULL, 6, '6 anos/200.000 km veículo + 8 anos/200.000 km bateria Blade', 'PHEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'Versão topo de linha do Atto 2 DM-i Flex, com bateria maior (18kWh vs 7,3kWh da GL) que mais que dobra a autonomia elétrica pura (110km vs 45km) e carregamento AC mais rápido (6,6kW vs 3,3kW). Inclui pacote ADAS 2, que a GL não tem. Autonomia combinada de 1.045km (gasolina, NEDC) ou 770km (etanol). Fabricada em Camaçari (BA), lançada em 9/jun/2026.', 'https://www.byd.com/material/byd-site/br/product/atto-2-dmi/atto2-header.webp', NULL, '{"urbano":3,"familia":4,"aventura":3,"performance":3,"custo":2}'::jsonb),
  ('byd-seal', 'BYD Seal', 'BYD', 'Sedã médio', 269800, 313, 360, 82.5, 'LFP (Blade), arquitetura CTB', 'PMSM traseiro (RWD) — versão Design', 372, NULL, NULL, 400, NULL, NULL, 11, 150, NULL, '6 anos veículo / 8 anos bateria', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 22.2, 'Preço varia entre fontes de R$269.800 a R$296.800 conforme a versão/momento. Existe também a versão Performance AWD, mais potente e cara, com 0-100 em 3,8s. Autonomia real PBEV/Inmetro de 372km é bem mais conservadora que os 570km que circulavam antes (provavelmente CLTC chinês).', 'https://www.byd.com/material/byd-site/america-public/header-product-image/seal/seal_glacier_blue.png', NULL, '{"urbano":2,"familia":3,"aventura":1,"performance":5,"custo":1}'::jsonb),
  ('byd-han-ev', 'BYD Han EV', 'BYD', 'Sedã grande premium', 559800, 517, 700, 76.9, 'LFP (Blade)', 'Bimotor AWD (um motor em cada eixo)', 480, 3.9, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '8 anos bateria', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 16, 'Preço real de tabela é R$559.800 — bem acima dos R$429.800 que circulavam antes. Autonomia fica entre 450-500km em ciclo combinado/WLTP (usamos a média, 480km); recarga rápida de 30% a 80% em ~25min.', 'https://www.byd.com/material/byd-site/america-public/header-product-image/han/han-black.png', NULL, '{"urbano":1,"familia":4,"aventura":1,"performance":5,"custo":1}'::jsonb),
  ('byd-song-plus-phev', 'BYD Song Plus PHEV', 'BYD', 'SUV híbrido', 250000, 235, NULL, 18.3, 'LFP (Blade)', 'PHEV combinado (1.5 aspirado + elétrico) — versão FWD', 1200, 7.9, NULL, 552, NULL, NULL, NULL, NULL, NULL, NULL, 'PHEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'Autonomia elétrica pura homologada de 68km (Inmetro). Existe também a versão Premium AWD (1.5 turbo + dois motores elétricos, 324cv, R$299.800, autonomia elétrica de 87km). Preço da versão FWD subiu de ~R$240 mil para ~R$250 mil entre gerações — bem acima dos R$219.800 que circulavam antes.', 'https://www.byd.com/material/byd-site/br/song-plus---update-2025/page-finais/banner-key-vision-pc.webp', NULL, '{"urbano":2,"familia":4,"aventura":3,"performance":4,"custo":2}'::jsonb),
  ('byd-king-phev', 'BYD King PHEV', 'BYD', 'Sedã compacto híbrido', 175990, 235, NULL, 6.6, 'LFP', 'PHEV combinado (1.5 + elétrico) — versão GS', 1175, NULL, NULL, 450, NULL, NULL, NULL, NULL, NULL, NULL, 'PHEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'Preço real de tabela é R$175.990 (versão GS) — bem abaixo dos R$279.800 que circulavam antes; a versão de entrada GL custa R$147.990 com 209cv e só 32km de autonomia elétrica. Bateria pequena (6,6kWh) é perfil híbrido leve, não plugável de longa autonomia elétrica: até 78km NEDC na GS. Consumo no modo combustão: até 16,8 km/l na cidade.', 'https://www.byd.com/material/byd-site/br/product/king/king-Header1.png', NULL, '{"urbano":4,"familia":3,"aventura":1,"performance":3,"custo":3}'::jsonb),
  ('byd-shark-phev', 'BYD Shark PHEV', 'BYD', 'Picape híbrida', 379800, 437, NULL, 29.8, NULL, 'PHEV combinado AWD (1.5 turbo 183cv + elétrico dianteiro 231cv + elétrico traseiro 204cv)', 840, 5.7, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '8 anos bateria + 5 anos cobertura total do veículo', 'PHEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'Autonomia elétrica pura de 57km (PBEV/Inmetro) ou até 100km (NEDC). Caçamba com 1.200 litros de capacidade. Tração integral (AWD), com motor a combustão 1.5 turbo (183cv/260Nm) somado a dois motores elétricos (231cv dianteiro + 204cv traseiro).', 'https://www.byd.com/material/byd-site/america-public/header-product-image/Header-BYD-SHARK.png', NULL, '{"urbano":1,"familia":3,"aventura":5,"performance":5,"custo":1}'::jsonb),
  ('byd-atto-8', 'BYD Atto 8', 'BYD', 'SUV híbrido premium', 399990, 488, 550, 35.6, 'LFP (Blade)', 'PHEV combinado AWD (1.5 turbo 156cv + elétrico dianteiro 272cv + elétrico traseiro 216cv)', 900, NULL, NULL, NULL, NULL, NULL, NULL, 72, 9, NULL, 'PHEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'SUV híbrido plug-in de 7 lugares com tração integral (AWD): motor 1.5 turbo (156cv) + motor elétrico dianteiro (272cv) + motor elétrico traseiro (216cv), somando 488cv combinados. Bateria Blade LFP de 35,6 kWh garante autonomia elétrica pura de até 152km; autonomia total combinada de até 900km (ciclo NEDC). Porta-malas de até 1.960L com os bancos rebatidos (capacidade com bancos em uso não divulgada). Recarga DC de 30-80% em ~20min (até 72kW). Lançado no Salão do Automóvel 2025.', 'https://www.byd.com/material/byd-site/br/atto-8/New_Atto_8_header_2.png', NULL, '{"urbano":2,"familia":5,"aventura":3,"performance":4,"custo":1}'::jsonb),
  ('byd-sealion-7', 'BYD Sealion 7', 'BYD', 'SUV médio premium', 339990, 531, 690, 82.5, 'LFP (Blade)', 'PMSM AWD biMotor (elétrico dianteiro + traseiro)', 360, 4.5, NULL, 500, NULL, NULL, 11, 150, NULL, '6 anos ou 200.000 km veículo / 8 anos ou 200.000 km bateria Blade', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 22.9, 'SUV cupê elétrico irmão do Seal, com tração integral AWD (531cv/690Nm) e 0-100km/h em 4,5s — um dos mais potentes e rápidos do comparativo inteiro. Bateria Blade LFP de 82,5kWh garante 360km de autonomia Inmetro. Porta-malas de 500L + frunk dianteiro de 58L. Recarga DC até 150kW (30-80% em ~30min).', 'https://www.byd.com/material/byd-site/br/product/sealion/imagens/header/Sealion7-header.webp', NULL, '{"urbano":2,"familia":3,"aventura":2,"performance":5,"custo":1}'::jsonb),
  ('byd-song-pro-dm-i-flex', 'BYD Song Pro DM-i Flex', 'BYD', 'SUV híbrido', 176990, 235, 299, NULL, NULL, 'PHEV combinado (1.5 Flex etanol/gasolina + elétrico) — FWD', 1105, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 6, NULL, 'PHEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'Primeiro SUV híbrido plug-in fabricado no Brasil pela BYD — motor 1.5 Flex (etanol ou gasolina) + elétrico somando 235cv e ~30,5 kgfm. Autonomia elétrica pura de até 72km (versão GS) e autonomia total combinada de até 1.105km. Preço de R$176.990 é da versão de entrada GL (já com desconto de venda direta); a versão GS sai por R$199.990.', 'https://www.byd.com/material/__CN/byd-site/br/product/songpro-flex/byd-song-pro-flex-HEADER-3.png', NULL, '{"urbano":3,"familia":4,"aventura":2,"performance":3,"custo":4}'::jsonb),
  ('byd-tan', 'BYD Tan', 'BYD', 'SUV grande premium', NULL, 517, 700, 108.8, 'LFP (Blade)', 'PMSM elétrico, tração integral 4x4', 430, NULL, NULL, NULL, NULL, NULL, NULL, 110, NULL, '8 anos bateria Blade', 'BEV', false, NULL, NULL, NULL, NULL, NULL, 25.3, 'SUV elétrico premium de 7 lugares, tração integral 4x4, 517cv e 700Nm, acelera de 0-100km/h em menos de 5s. Bateria Blade LFP gigante de 108,8kWh rende até 430km Inmetro (530km no ciclo WLTP, mais otimista). Porta-malas varia de 235L (7 lugares) a 940L (5 lugares) e 1.655L com os bancos rebatidos. Recarga DC de 30-80% em ~30min a 110kW. Preço não incluído: fontes divergem entre R$529.890 e R$536.800 e não conseguimos confirmar o valor exato de tabela atual — confira na concessionária.', 'https://www.byd.com/material/byd-site/america-public/header-product-image/new-tan-grey-header.png', NULL, '{"urbano":1,"familia":5,"aventura":2,"performance":4,"custo":1}'::jsonb),
  ('byd-yuan-pro', 'BYD Yuan Pro', 'BYD', 'SUV híbrido', NULL, 212, 300, 18, NULL, 'PHEV combinado (1.5 aspirado 98cv + elétrico 197cv) — FWD', 1000, 7.5, NULL, 440, NULL, NULL, NULL, 60, NULL, '8 anos bateria / 5 anos veículo', 'PHEV', false, NULL, NULL, NULL, NULL, NULL, NULL, 'SUV híbrido plug-in listado no site oficial da BYD Brasil, mas ainda sem preço oficial confirmado publicamente (estimativa de mercado entre R$180-220 mil) — não incluímos preço pra não arriscar um valor errado. Motor 1.5 aspirado (98cv) + elétrico (197cv), somando 212cv e ~30,6 kgfm. Bateria de 18kWh rende até 110km no ciclo chinês NEDC (na prática, algo entre 80-100km em condições brasileiras). Autonomia combinada acima de 1.000km. Recarga DC (60kW) de 30-80% em 30-40min.', 'https://www.byd.com/material/byd-site/america-public/header-product-image/header-yuanpro.png', NULL, '{"urbano":4,"familia":3,"aventura":2,"performance":2,"custo":4}'::jsonb),
  ('mg-mg4', 'MG4 Comfort', 'MG', 'Hatch médio', 169990, 190, 350, 64, 'LFP', 'PMSM traseiro (RWD)', 364, 7.2, 132, 350, 1755, 'Incluso, sem custo', 11, 140, 6, '7 anos/150.000 km veículo / 8 anos/160.000 km bateria', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 17, 'Versão de entrada da linha MG4 (distinta da ''MG4 Urban Luxury 54 kWh'' já cadastrada separadamente, um modelo menor e mais barato). Existem também Luxury RWD 64kWh (mesma potência/bateria, mais equipamento) e XPower AWD 64kWh (320kW/435cv, 0-100 em 3,8s, R$249.000). Autonomia 364km é a homologada Inmetro/PBEV (a WLTP divulgada pela MG é 467km, mas superestima o uso real no Brasil). Ficha conferida na ficha técnica oficial MG (ago/2026).', 'https://mgmotoroficial.com.br/imagens/mg4/img-kv-mg4-cortada-3.webp', NULL, '{"urbano":4,"familia":4,"aventura":2,"performance":4,"custo":3}'::jsonb),
  ('mg-s5', 'MG S5', 'MG', 'SUV médio', 218800, 205, 350, 62, 'LFP', 'PMSM traseiro (RWD)', 351, 6.3, 136, 453, 1705, NULL, 7, 150, 6, '7 anos/150.000 km veículo, 8 anos/160.000 km bateria', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 17.7, 'Duas versões: Comfort (R$195.800, reajustada pra R$218.800 a partir de 5/jan/2026 — ficha usada aqui, com 6 airbags) e Luxury (R$219.800, R$238.800 após 5/jan/2026, ganha 7º airbag central, teto solar e mais equipamento). Construído sobre a Plataforma Modular Escalável (MSP) da MG, 5 estrelas no Euro NCAP 2025.', 'https://mgmotoroficial.com.br/imagens/mgs5/mgs5-comfort.webp', NULL, '{"urbano":3,"familia":4,"aventura":2,"performance":4,"custo":3}'::jsonb),
  ('mg-cyberster', 'MG Cyberster', 'MG', 'Roadster conversível premium', 499800, 510, 725, 77, NULL, 'Bimotor AWD sob demanda', 342, 3.2, NULL, NULL, NULL, NULL, NULL, 150, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 22.5, 'Roadster esportivo com portas de abertura tipo tesoura. Recarga DC de 150kW leva de 10% a 80% em ~38min.', 'https://mgmotoroficial.com.br/imagens/cyberster/cyberster-color-sombra/cyberster-color-red.webp', NULL, '{"urbano":2,"familia":1,"aventura":1,"performance":5,"custo":1}'::jsonb),
  ('gac-aion-es', 'GAC Aion ES', 'GAC', 'Sedã compacto', 169990, 136, 225, 55.2, NULL, 'PMSM dianteiro (FWD)', 314, NULL, NULL, 453, NULL, NULL, NULL, 75, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 17.6, 'Recarga DC de 75kW leva a bateria de 30% a 80% em ~37min.', 'https://br-www-resouce-cdn.gacgroup.com/static/BR/tenant/cms/common/202505/63deb344-57d5-449f-bcf7-1333ea1150f9.webp', NULL, '{"urbano":4,"familia":4,"aventura":2,"performance":2,"custo":4}'::jsonb),
  ('gac-aion-y', 'GAC Aion Y Premium', 'GAC', 'SUV compacto', 175990, 204, 225, 63.2, NULL, 'PMSM dianteiro (FWD)', 316, 8.5, NULL, 361, NULL, NULL, NULL, NULL, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 20, 'Também comercializado como minivan/SUV familiar; existe versão Elite mais em conta.', 'https://br-www-resouce-cdn.gacgroup.com/static/BR/tenant/cms/common/202503/c9cae70c-c9ca-4488-b909-541e01608a37.jpg', NULL, '{"urbano":3,"familia":5,"aventura":2,"performance":3,"custo":3}'::jsonb),
  ('gac-aion-v', 'GAC Aion V Elite', 'GAC', 'SUV médio', 219990, 204, 240, 75.4, NULL, 'PMSM dianteiro (FWD)', 389, 8, NULL, 427, NULL, NULL, NULL, NULL, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 19.4, 'Versão única (Elite) no Brasil.', 'https://br-www-resouce-cdn.gacgroup.com/static/BR/tenant/cms/common/202509/1757388789199-%E5%B7%B4%E8%A5%BFv%E5%A4%96%E8%A7%82%E9%A2%9C%E8%89%B2-1.jpg', NULL, '{"urbano":3,"familia":4,"aventura":3,"performance":3,"custo":2}'::jsonb),
  ('gac-hyptec-ht', 'GAC Hyptec HT Elite', 'GAC', 'SUV médio premium', 314990, 340, 430, 83, NULL, 'PMSM traseiro (RWD) — motorização da linha 2027 não totalmente detalhada em fonte confiável', 431, 5.8, NULL, 670, NULL, NULL, NULL, NULL, NULL, '8 anos bateria (termo herdado da geração anterior, não confirmado se se mantém igual na versão 2027)', 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 19.3, 'SUV cupê elétrico da Hyptec, submarca premium da GAC. Linha 2027 lançada em 2026 com bateria ampliada (83kWh, arquitetura 800V) e mais potência (340cv/430Nm) que a geração anterior (245cv/72,7kWh). Duas versões: Elite (R$314.990 — ficha usada aqui) e Ultra (R$369.990, com portas traseiras de abertura vertical). Recarga DC de 30-80% em ~15min. Consumo de 19,3 kWh/100km calculado a partir de bateria/autonomia oficiais.', 'https://br-www-resouce-cdn.gacgroup.com/static/BR/tenant/cms/common/202604/1776324386180-1-pc.webp', NULL, '{"urbano":3,"familia":4,"aventura":3,"performance":5,"custo":1}'::jsonb),
  ('leapmotor-b10', 'Leapmotor B10', 'Leapmotor', 'SUV compacto', 182990, 218, 240, 56.2, NULL, 'PMSM traseiro (RWD)', 288, 8, NULL, 430, NULL, NULL, NULL, NULL, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 19.5, 'Autonomia WLTP divulgada é 361km, mas a homologação Inmetro/PBEV real é 288km. Preço de tabela varia por público: R$182.990 padrão, com descontos pra troca de usado (R$175.990), taxista (R$141.190), PCD (R$161.390) e CNPJ (R$168.290). Será fabricado no Brasil em fábrica da Stellantis. Recarga rápida recupera 50% em ~15min.', 'https://www.leapmotor.com.br/content/dam/leapmotor/products/487/tac/2/2027/page/hero-webp/hero-0UB.webp', NULL, '{"urbano":4,"familia":4,"aventura":2,"performance":4,"custo":3}'::jsonb),
  ('leapmotor-c10', 'Leapmotor C10', 'Leapmotor', 'SUV médio', 204990, 218, 320, 69.9, NULL, 'PMSM traseiro (RWD)', 338, 8.3, NULL, 465, NULL, NULL, NULL, NULL, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 20.7, 'Existe também a versão REEV (com extensor de autonomia a combustão), cadastrada separadamente (id leapmotor-c10-reev) por ser um powertrain diferente (fuelType PHEV em vez de BEV).', 'https://www.leapmotor.com.br/content/dam/leapmotor/products/488/cab/2/2027/page/hero-webp/hero-0YF.webp', NULL, '{"urbano":3,"familia":5,"aventura":3,"performance":4,"custo":2}'::jsonb),
  ('leapmotor-c10-reev', 'Leapmotor C10 REEV', 'Leapmotor', 'SUV médio', 219990, 215, 320, 28.4, 'LFP', 'REEV — motor elétrico traseiro (RWD) + gerador a combustão 1.5 4cc (não traciona as rodas)', 1050, NULL, NULL, 465, NULL, NULL, NULL, NULL, NULL, NULL, 'PHEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'Versão REEV (range extender EV) do C10: motor a combustão 1.5 de 4 cilindros funciona só como gerador pra recarregar a bateria, sem tracionar as rodas diretamente — tração é sempre elétrica traseira. Bateria LFP de 28,4kWh dá ~145km de autonomia elétrica pura (WLTP); com o tanque de 50L cheio, a autonomia combinada chega a 950-1.150km. Recarga DC de 30-80% em 18-30min. Porta-malas assumido igual ao da versão BEV (mesma carroceria, 465L) — não há fonte específica confirmando pra versão REEV.', 'https://www.leapmotor.com.br/content/dam/leapmotor/products/488/cag/2/2027/page/hero-webp/hero-0GD.webp', NULL, '{"urbano":3,"familia":5,"aventura":3,"performance":3,"custo":2}'::jsonb),
  ('geely-ex5', 'Geely EX5 Pro', 'Geely', 'SUV médio', 205800, 218, 320, 60.2, NULL, 'PMSM dianteiro (FWD)', 413, 6.9, NULL, 461, NULL, NULL, NULL, NULL, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 14.6, 'Versão Pro (R$205.800) tem autonomia de 413km; a Max (R$225.800) cai pra 349km com mais equipamentos. Existe também a versão híbrida plug-in EX5 EM-i, cadastrada separadamente (id geely-ex5-em-i) por ser outro powertrain (fuelType PHEV em vez de BEV).', 'https://static.autodromo.com.br/uploads/51bca4b0-a28b-455b-9ed2-7647ccc8deec_4.webp', NULL, '{"urbano":3,"familia":4,"aventura":3,"performance":4,"custo":3}'::jsonb),
  ('geely-ex5-em-i', 'Geely EX5 EM-i Pro', 'Geely', 'SUV híbrido', 189990, 262, 380, 18.4, NULL, 'PHEV combinado ''Super Híbrido'' (1.5 aspirado + elétrico)', 1300, 7.8, NULL, 428, NULL, NULL, NULL, NULL, 6, NULL, 'PHEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'Primeiro veículo da Geely com produção nacional (Complexo Industrial Ayrton Senna, São José dos Pinhais/PR), ainda em 2026. Três versões: Pro (R$189.990, bateria 18,4kWh, ~65km elétricos — ficha usada aqui), Max (R$209.990, mesma bateria) e Ultra (R$234.990, bateria maior de 29,8kWh, ~112km elétricos Inmetro, com carregamento DC de até 60kW — as versões Pro/Max não têm DC confirmado). Autonomia combinada de até 1.300km. Porta-malas de 428L (até 2.000L com bancos rebatidos).', 'https://static.autodromo.com.br/uploads/51bca4b0-a28b-455b-9ed2-7647ccc8deec_4.webp', NULL, '{"urbano":3,"familia":4,"aventura":3,"performance":4,"custo":2}'::jsonb),
  ('omoda-e5', 'Omoda E5', 'Omoda', 'SUV compacto', 209990, 204, 340, 61.1, NULL, 'PMSM dianteiro (FWD)', 345, 7.6, NULL, 360, NULL, NULL, NULL, 80, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 17.7, 'Derivado do modelo híbrido Omoda 5. Recarga DC de 80kW leva de 30% a 80% em ~30min.', 'https://cms.omodajaecoo.com.br/images/vehicles-content/1357281428-168782880-img-desk.jpg', NULL, '{"urbano":3,"familia":4,"aventura":2,"performance":3,"custo":3}'::jsonb),
  ('omoda-7-shs-p', 'Omoda 7 SHS-P', 'Omoda', 'SUV híbrido', 254990, 279, 365, 18.4, NULL, 'PHEV combinado (1.5 turbo 99kW + elétrico 150kW/310Nm)', 1200, 8.4, NULL, 590, 1795, NULL, NULL, NULL, 8, '8 anos/150.000 km bateria', 'PHEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'SUV híbrido plug-in irmão do JAECOO 7 PHEV (mesma plataforma Chery Super Hybrid System, specs quase idênticas: 279cv/365Nm, bateria 18,4kWh, ~60km elétricos Inmetro, 1.200km combinados). O ''SHS-P'' (Plug-in) distingue do Omoda 5 SHS-H, que é HEV comum sem tomada — por isso não entrou na base. Duas versões: Luxury (R$254.990 — ficha usada aqui) e Prestige (R$279.990).', 'https://cms.omodajaecoo.com.br/images/omoda7/O7_DESIGN_E_CONFORTO/O7_DeC_1920x1080_EXTERNA.jpg', NULL, '{"urbano":3,"familia":4,"aventura":3,"performance":4,"custo":1}'::jsonb),
  ('zeekr-x', 'Zeekr X Flagship', 'Zeekr', 'SUV compacto', 338000, 428, 532, 66, NULL, 'Bimotor AWD (um em cada eixo) — versão Flagship', 332, 3.8, NULL, NULL, NULL, NULL, NULL, 150, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 19.9, 'O preço de R$189.990 que circulava antes está bem abaixo de qualquer versão real vendida no Brasil. Ficha usada aqui é a Flagship, biMotor AWD (R$338 mil). Existem versões de entrada mais baratas — Privilege (~R$309 mil) e Premium (~R$298 mil) — com potência e bateria menores, ainda não detalhadas em fonte confiável. Recarga DC de 150kW leva de 10% a 80% em ~20min; carga AC completa em ~3h.', 'https://www.datocms-assets.com/146515/1752768085-mobile-x.png', NULL, '{"urbano":2,"familia":3,"aventura":2,"performance":5,"custo":1}'::jsonb),
  ('zeekr-001', 'Zeekr 001 Premium', 'Zeekr', 'Sedã grande premium', 495000, 544, 686, 100, 'NMC', 'Bimotor AWD', 426, 3.8, 174, 2144, 2225, NULL, 22, 200, 7, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 23.5, '''Shooting brake premium'' (sedã grande com traseira estilo perua), primeiro modelo da Zeekr no Brasil. Duas versões, Premium (R$495 mil — ficha usada aqui) e Flagship (R$542 mil), com mecânica idêntica (544cv/686Nm, bateria 100kWh NMC) — só vão livre (174mm vs 162mm) e equipamentos mudam. Preço subiu bastante desde o lançamento (R$428 mil). Porta-malas de 2.144L é o volume máximo com bancos rebatidos e frunk incluso. Recarga DC de até 200kW (arquitetura 800V).', 'https://www.datocms-assets.com/146515/1752768085-mobile-001.png', NULL, '{"urbano":1,"familia":4,"aventura":1,"performance":5,"custo":1}'::jsonb),
  ('zeekr-7x', 'Zeekr 7X', 'Zeekr', 'SUV médio premium', 448000, 646, 710, 100, NULL, 'Bimotor AWD (224cv dianteiro + 422cv traseiro)', 423, NULL, NULL, 539, NULL, NULL, NULL, 200, 7, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 23.6, 'SUV elétrico mais potente da linha Zeekr no Brasil (646cv/710Nm combinados, bimotor AWD). Bateria de 100kWh dá 423km Inmetro. Recarga DC de até 200kW (80% em ~30min). Porta-malas de 539L.', 'https://www.datocms-assets.com/146515/1753086881-cx1e_eu_f3q_20_longrange_rwd_black-2.png', NULL, '{"urbano":2,"familia":4,"aventura":3,"performance":5,"custo":1}'::jsonb),
  ('neta-x-400', 'Neta X 400', 'Neta', 'SUV compacto', 194900, 163, NULL, 52.5, NULL, NULL, 258, NULL, NULL, NULL, 1670, NULL, NULL, NULL, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 20.3, 'Baterias fabricadas pela CATL. Carregamento AC completo em ~9h; DC de 30% a 80% em ~30min. Versão de entrada da linha Neta X.', 'https://netaauto.com.br/wp-content/webp-express/webp-images/uploads/2025/06/NETA-X-8.jpg.webp', NULL, '{"urbano":3,"familia":4,"aventura":2,"performance":2,"custo":3}'::jsonb),
  ('neta-x-500', 'Neta X 500', 'Neta', 'SUV compacto', 204900, 163, NULL, 64.1, NULL, NULL, 317, NULL, NULL, NULL, 1740, NULL, NULL, NULL, NULL, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 20.2, 'Baterias fabricadas pela CATL. Carregamento AC completo em ~11h; DC de 30% a 80% em ~30min. Existe também a versão 500 Luxury, com peso e bateria equivalentes.', 'https://netaauto.com.br/wp-content/webp-express/webp-images/uploads/2025/06/NETA-X-8.jpg.webp', NULL, '{"urbano":3,"familia":4,"aventura":2,"performance":2,"custo":3}'::jsonb),
  ('neta-gt', 'Neta GT', 'Neta', 'Cupê esportivo elétrico', NULL, 394, 620, 74.48, NULL, 'Bimotor AWD (um em cada eixo, 145kW cada)', 410, 3.7, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BEV', false, NULL, NULL, NULL, NULL, NULL, 18.2, 'Cupê esportivo 2+2 elétrico da Neta, revelado no Festival Interlagos (ago/2024) e comercializado desde set/2024 por concessionárias oficiais (netaauto.com.br, netaautopotenza.com.br), mas sem preço oficial divulgado publicamente até hoje (mesmo passados quase 2 anos do lançamento) — deixado como null. Bimotor AWD com 394cv/620Nm combinados, bateria de 74,48kWh, acelera 0-100km/h em 3,7s. Baterias CATL, como o resto da linha Neta.', 'https://netaauto.com.br/wp-content/webp-express/webp-images/uploads/2024/08/06_NetaGT_Azul_Estrada_Frente.png.webp', NULL, '{"urbano":2,"familia":2,"aventura":1,"performance":5,"custo":3}'::jsonb),
  ('volvo-ex90', 'Volvo EX90', 'Volvo', 'SUV grande premium', 849990, 517, 860, 111, NULL, 'Bimotor AWD', 459, 4.9, NULL, 310, 2757, NULL, NULL, 350, 9, NULL, 'BEV', true, '17/08/2026', NULL, NULL, NULL, NULL, 24.2, 'SUV elétrico grande e mais caro da Volvo, com 7 lugares — o primeiro totalmente elétrico da marca nessa configuração. Lançado no Brasil em abr/2025 por R$849.950; linha 2026 ganhou arquitetura 800V, permitindo recarga DC de até 350kW (10-80% em ~30min, adicionando até 250km em 10min). Bimotor AWD com 517cv/860Nm. Tem Lidar de série e 9 airbags. Porta-malas varia de 310L (7 lugares) a 654L (5 lugares).', 'https://www.volvocars.com/images/cs/v3/assets/blt0feaa88e629251fc/blt88ae6c8936a0e087/68089476b435297d2888d1ae/overview-exterior-gallery-16x9.jpg?branch=prod_alias&quality=85&format=auto&h=1200&w=1800', NULL, '{"urbano":1,"familia":5,"aventura":2,"performance":5,"custo":1}'::jsonb),
  ('volvo-xc60-recharge-t8', 'Volvo XC60 Recharge T8', 'Volvo', 'SUV híbrido premium', 459950, 462, 696, 18.8, NULL, 'PHEV combinado AWD (2.0 turbo 320cv + elétrico 87cv)', NULL, 4.8, NULL, 468, NULL, NULL, NULL, NULL, 8, NULL, 'PHEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'SUV médio híbrido plug-in, líder de vendas entre híbridos da Volvo no Brasil (3.287 unidades em 2024). Quatro versões — Plus (R$459.950, ficha usada aqui), Ultra (~R$509.950), Ultra Dark (R$519.950) e Polestar Engineered (R$539.950) — compartilham a mesma mecânica T8 (462cv/696Nm combinados), só equipamento muda. Bateria de 18,8kWh dá até 44km de autonomia elétrica (Inmetro) ou 80km (WLTP).', 'https://www.volvocars.com/images/cs/v3/assets/bltab26d231d43e6180/blted43c61a243553ba/67d020e6fabac283d0083243/xc60-phev-my25.png?branch=prod_alias&quality=85&format=auto&h=1080&w=1920', NULL, '{"urbano":3,"familia":4,"aventura":3,"performance":5,"custo":1}'::jsonb),
  ('volvo-xc90-recharge-t8', 'Volvo XC90 Recharge T8', 'Volvo', 'SUV grande híbrido premium', 679950, 462, 709, 18.8, NULL, 'PHEV combinado AWD (2.0 turbo 317cv + elétrico traseiro 145cv)', NULL, NULL, 223, 316, NULL, NULL, 7, NULL, NULL, '2 anos (termo de garantia da bateria não confirmado — costuma ser 8 anos/160.000km em outros modelos Volvo com T8)', 'PHEV', true, '17/08/2026', NULL, NULL, NULL, NULL, NULL, 'SUV grande híbrido plug-in de 7 lugares, ainda em linha no Brasil mesmo após o lançamento do EX90 (100% elétrico) — não foi substituído, coexistem no catálogo. Versão Plus, mesma mecânica T8 (462cv/709Nm) do XC60. Bateria de 18,8kWh dá 47km de autonomia elétrica. Porta-malas de 316L com as 3 fileiras em uso (500L com a 3ª rebatida). Vão livre de 223mm.', 'https://www.volvocars.com/images/cs/v3/assets/bltab26d231d43e6180/blt13250d579061ab3e/67d154a186708c44edcaedf4/xc90-phev-my24.png?branch=prod_alias&quality=85&format=auto&h=1080&w=1920', NULL, '{"urbano":2,"familia":5,"aventura":2,"performance":5,"custo":1}'::jsonb),
  ('byd-dolphin-mini', 'BYD Dolphin Mini', 'BYD', 'Hatch compacto', 119990, 95, NULL, NULL, NULL, NULL, 340, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BEV', false, '15/08/2026', NULL, NULL, NULL, NULL, 11.5, '', NULL, NULL, '{"urbano":5,"familia":2,"aventura":2,"performance":1,"custo":5}'::jsonb),
  ('mg-mg4-vers-o-importada-', 'MG MG4 (versão importada)', 'MG', 'Hatch médio', 189990, 203, NULL, NULL, NULL, NULL, 435, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'BEV', false, NULL, NULL, NULL, NULL, NULL, 14.5, '', NULL, NULL, '{"urbano":4,"familia":3,"aventura":2,"performance":3,"custo":3}'::jsonb)
